def predict(board, action):
    if isinstance(action, tuple):
        row, col = action
    else:
        row, col = action[0], action[1]

    old_char = board[row][col]
    new_char = 'B' if old_char == 'Y' else old_char

    board_list = [list(row) for row in board]
    board_list[row][col] = new_char
    return [''.join(row) for row in board_list]
